import numpy as np
import scipy.linalg

def solve(problem):
    A = problem['matrix']
    L = scipy.linalg.cholesky(A, lower=True, check_finite=False, overwrite_a=False)
    return {'Cholesky': {'L': L}}

import numpy as np
from scipy.linalg import lu

def solve(problem):
    A = np.asarray(problem['matrix'], dtype=np.float64)
    P, L, U = lu(A)
    return {'LU': {'P': P.tolist(), 'L': L.tolist(), 'U': U.tolist()}}
